import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:sineobex_field/api/generated/api.dart' show MatchBand, MatchReason;
import 'package:sineobex_field/patients/dob.dart';
import 'package:sineobex_field/patients/match_constants.dart';
import 'package:sineobex_field/patients/matching.dart';

/// The worked examples of design 5.3 and the done-when's expected phone scores, hand-checked until
/// match.json, generated by the matching work from the server's scorer, lands.
void main() {
  final doneWhen = jsonDecode(
    File('../../packages/contract/test-vectors/done-when.json').readAsStringSync(),
  ) as Map<String, Object?>;

  MatchName preferred(String s) => MatchName(NameSource.preferred, s);
  MatchName alias(String s) => MatchName(NameSource.alias, s);

  group('tokens', () {
    test('an exact token is 1, a nickname 0.9, a typo by edit distance or trigrams', () {
      expect(tokSim('del', 'del'), 1);
      expect(tokSim('mike', 'michael'), nicknameSim);
      expect(tokSim('smity', 'smitty'), closeTo(1 - 1 / 6, 1e-12));
      expect(tokSim('jones', 'mike'), closeTo(0.2, 1e-12));
      expect(tokSim('j', 'jones'), initialSim);
      expect(tokSim('jones', 'j'), initialSim);
      expect(tokSim('smi', 'smitty'), lessThan(prefixSim));
      expect(tokSim('smi', 'smitty', search: true), prefixSim);
    });

    test('nicknames share a line of the data, in both directions', () {
      expect(areNicknames('pepe', 'jose'), isTrue);
      expect(areNicknames('jose', 'pepe'), isTrue);
      expect(areNicknames('jose', 'jose'), isFalse);
      expect(areNicknames('jose', 'mike'), isFalse);
      expect(nicknamesOf('chuy'), containsAll(['jesus', 'chucho']));
      expect(nicknamesOf('chuy'), isNot(contains('chuy')));
    });

    test('optimal string alignment counts a swap of neighbours as one edit', () {
      expect(osaDistance('smity', 'smitty'), 1);
      expect(osaDistance('smitty', 'smtity'), 1);
      expect(osaDistance('jones', 'mike'), 4);
      expect(osaDistance('', 'abc'), 3);
      expect(osaDistance('ca', 'abc'), 3);
    });
  });

  group('births', () {
    test('two full dates', () {
      double? sim(Birth a, Birth b) => dobSim(a, b)?.sim;
      expect(sim(const BirthDate(1946, 3, 7), const BirthDate(1946, 3, 7)), 1);
      expect(sim(const BirthDate(1946, 7, 3), const BirthDate(1946, 3, 7)), dobSwapped);
      expect(sim(const BirthDate(1946, 3, 9), const BirthDate(1946, 3, 7)), dobMonthYear);
      expect(sim(const BirthDate(1964, 3, 7), const BirthDate(1946, 3, 7)), dobYearSlip);
      expect(sim(const BirthDate(1947, 3, 7), const BirthDate(1946, 3, 7)), dobYearSlip);
      expect(sim(const BirthDate(1956, 3, 7), const BirthDate(1946, 3, 7)), dobYearSlip);
      expect(sim(const BirthDate(1946, 11, 7), const BirthDate(1946, 3, 7)), dobYear);
      expect(sim(const BirthDate(1950, 11, 7), const BirthDate(1946, 3, 7)), 0);
      expect(dobSim(const BirthDate(1950, 11, 7), const BirthDate(1946, 3, 7))?.reason, isNull);
    });

    test('years, estimates and unknowns', () {
      expect(dobSim(const BirthYear(1946), const BirthDate(1946, 3, 7))?.sim, yearSame);
      expect(dobSim(const BirthYear(1946), const BirthYear(1947))?.sim, yearNear);
      expect(dobSim(const BirthYear(1946), const BirthYear(1948))?.sim, 0);
      expect(dobSim(const BirthEstimate(1980), const BirthDate(1983, 1, 1))?.sim, estimateNear);
      expect(dobSim(const BirthEstimate(1980), const BirthYear(1984))?.sim, 0);
      expect(dobSim(null, const BirthYear(1946)), isNull);
    });
  });

  group('search', () {
    test('the done-when: "Smity" finds Del through his street name', () {
      final p1 = doneWhen['p1']! as Map<String, Object?>;
      final expected = (doneWhen['search']! as Map<String, Object?>)['expected']! as Map<String, Object?>;
      final del = MatchPatient(
        patientId: p1['id']! as String,
        names: [
          preferred(p1['preferredName']! as String),
          for (final a in (p1['aliases']! as List<Object?>).cast<Map<String, Object?>>()) alias(a['alias']! as String),
          MatchName(NameSource.descriptor, p1['visualDescriptor']! as String),
        ],
        births: [Birth.fromJson(p1['birth'])!],
      );
      final query = SearchQuery(text: (doneWhen['search']! as Map<String, Object?>)['text']! as String);
      final score = scoreSearch(query, del);
      expect(score.score, closeTo(expected['phoneScore']! as double, 1e-9));
      expect([for (final r in score.reasons) r.wire], expected['reasons']);
      expect(rankSearch(query, [del]).single.patient.patientId, expected['first']);
    });

    test('a description counts less, and a birth blends in', () {
      final p = MatchPatient(
        patientId: 'a',
        names: [MatchName(NameSource.descriptor, 'Demo: tall, grey beard, red cap')],
        births: const [BirthDate(1946, 3, 7)],
      );
      expect(scoreSearch(SearchQuery(text: 'red cap'), p).score, closeTo(descriptorWeight, 1e-12));
      final withBirth = scoreSearch(SearchQuery(text: 'red cap', birth: const BirthDate(1946, 7, 3)), p);
      expect(withBirth.score, closeTo(0.7 * descriptorWeight + 0.3 * dobSwapped, 1e-12));
      expect(withBirth.reasons, [MatchReason.descriptor, MatchReason.dobSwapped]);
      // A birth date alone scores the birth; a year alone never searches.
      expect(scoreSearch(SearchQuery(birth: const BirthDate(1946, 3, 7)), p).score, 1);
      expect(SearchQuery(birth: const BirthYear(1946)).isEmpty, isTrue);
      expect(rankSearch(SearchQuery(birth: const BirthYear(1946)), [p]), isEmpty);
    });

    test('"Big Mike" finds Mike, and "Mike" finds Michael Jones', () {
      final mike = MatchPatient(patientId: 'm', names: [preferred('Michael Jones')]);
      expect(scoreSearch(SearchQuery(text: 'Big Mike'), mike).score, nicknameSim);
      expect(scoreSearch(SearchQuery(text: 'Mike'), mike).reasons, [MatchReason.name, MatchReason.nickname]);
    });

    test('ranks by score, then most recently seen, then ID, and cuts', () {
      final seen = DateTime.utc(2026, 10, 1);
      final candidates = [
        MatchPatient(patientId: 'c', names: [preferred('Smitty')]),
        MatchPatient(patientId: 'b', names: [preferred('Smitty')], lastSeen: seen),
        MatchPatient(patientId: 'a', names: [preferred('Smitty')]),
        MatchPatient(patientId: 'd', names: [preferred('Smity')], lastSeen: seen.add(const Duration(days: 9))),
        MatchPatient(patientId: 'e', names: [preferred('Rosa')]),
      ];
      final ranked = rankSearch(SearchQuery(text: 'smitty'), candidates);
      expect([for (final r in ranked) r.patient.patientId], ['b', 'a', 'c', 'd']);
      expect(rankSearch(SearchQuery(text: 'smitty'), candidates, limit: 2), hasLength(2));
    });
  });

  group('match', () {
    test('the done-when: the intake is likely Del, through his name, his street name and a swapped birth', () {
      final p1 = doneWhen['p1']! as Map<String, Object?>;
      final intake = doneWhen['intake']! as Map<String, Object?>;
      final legal = intake['legalName']! as Map<String, Object?>;
      final expected = (doneWhen['match']! as Map<String, Object?>)['expected']! as Map<String, Object?>;
      final subject = MatchPatient(
        names: [
          preferred(intake['preferredName']! as String),
          MatchName.legal(legal['given'] as String?, legal['family'] as String?),
        ],
        births: [Birth.fromJson(intake['birth'])!],
      );
      // The phone's index: no legal name (D40).
      final del = MatchPatient(
        patientId: p1['id']! as String,
        names: [
          preferred(p1['preferredName']! as String),
          for (final a in (p1['aliases']! as List<Object?>).cast<Map<String, Object?>>()) alias(a['alias']! as String),
        ],
        births: [Birth.fromJson(p1['birth'])!],
      );
      final score = scoreMatch(subject, del);
      expect(score.score, closeTo(expected['phoneScore']! as double, expected['tolerance']! as double));
      expect(score.band.wire, expected['band']);
      expect([for (final r in score.reasons) r.wire], expected['reasons']);
      expect(rankMatches(subject, [del]).single.patient.patientId, expected['candidate']);
    });

    test('the worked examples of design 5.3', () {
      final jon = scoreMatch(
        MatchPatient(names: [preferred('Jon Smith')], births: const [BirthDate(1946, 3, 14)]),
        MatchPatient(patientId: 'j', names: [preferred('John Smith')], births: const [BirthDate(1946, 3, 14)]),
      );
      expect(jon.score, closeTo(wName * 0.95 + wDob, 1e-12));
      expect(jon.band, MatchBand.likely);
      expect(jon.reasons, [MatchReason.name, MatchReason.nickname, MatchReason.dobExact]);

      final mike = scoreMatch(
        MatchPatient(names: [preferred('Mike')]),
        MatchPatient(patientId: 'm', names: [preferred('Michael Jones')]),
      );
      expect(mike.score, closeTo((0.9 + 0.9 + 0.2) / 3 * noDobFactor, 1e-12));
      expect(mike.band, MatchBand.weak);

      final smitty = scoreMatch(
        MatchPatient(names: [alias('Smitty')]),
        MatchPatient(patientId: 's', names: [alias('Smitty')]),
      );
      expect(smitty.score, singleNameCap);
      expect(smitty.band, MatchBand.possible);
      expect(smitty.score, lessThan(queueThreshold));

      final sameBirth = scoreMatch(
        MatchPatient(names: [preferred('Rosa Delgado')], births: const [BirthDate(1946, 3, 7)]),
        MatchPatient(patientId: 'x', names: [preferred('Tom Wexler')], births: const [BirthDate(1946, 3, 7)]),
      );
      expect(sameBirth.score, lessThanOrEqualTo(dobOnlyCap));
    });

    test('two different full birth dates cap the score', () {
      final conflict = scoreMatch(
        MatchPatient(names: [preferred('Del Smith')], births: const [BirthDate(1980, 1, 2)]),
        MatchPatient(patientId: 'd', names: [preferred('Del Smith')], births: const [BirthDate(1946, 7, 9)]),
      );
      expect(conflict.score, dobConflictCap);
    });

    test('the description never matches, and an intake never matches its own group', () {
      final p = MatchPatient(patientId: 'p', names: [MatchName(NameSource.descriptor, 'Demo: red cap')]);
      expect(
        scoreMatch(MatchPatient(names: [MatchName(NameSource.descriptor, 'Demo: red cap')]), p).score,
        lessThanOrEqualTo(dobOnlyCap),
      );
      final del = MatchPatient(patientId: 'd', names: [preferred('Del')], births: const [BirthYear(1946)]);
      final edit = MatchPatient(patientId: 'd', names: [preferred('Del')], births: const [BirthYear(1946)]);
      expect(rankMatches(edit, [del]), isEmpty);
    });
  });
}
